                        parts.append(f'[TOOL_RESULT {s[:200]}]')
            txt = '\n'.join(parts)
        else:
            txt = str(content)[:200]
        if txt.strip():
            print(f'--- {t} {l.get(\"timestamp\")} ---')
            print(txt[:800])
            print()
